body_md:
\label{t:ind} Consider for every positive integer $n$ the $n\times n$ random
matrix
\begin{equation}
\mathcal{M}_{n}=n^{-1}S_{n}X_{n}^{T}K_{n}X_{n}S_{n},  \label{mncal}
\end{equation} 
where:

\smallskip (a) $S_{n}$ is a positive definite $n\times n$ matrix such that
\begin{equation}
\sup_{n}n^{-1}\mathrm{Tr}R_{n}^{2}=r_{2}<\infty ,\;R_{n}=S_{n}^{2},
\label{r2}
\end{equation} 
and
\begin{equation}
\lim_{n\rightarrow \infty }\nu _{R_{n}}=\nu _{R},\;\nu _{R}(\mathbb{R} 
_{+})=1,  \label{nur}
\end{equation} 
where $\nu _{R_{n}}$ is the Normalized Counting Measure of $R_{n}$, $\nu
_{R} $ is a non-negative measure not concentrated at zero and $ 
\lim_{n\rightarrow \infty }$ denotes the weak convergence of probability
measures (see \cite{Sh:96}, Section III.1);

\smallskip (b) $X_{n}$ is the $n\times n$ random matrix
\begin{equation}
X_{n}=\{X_{j\alpha }\}_{j,\alpha =1}^{n},\;\mathbf{E}\{X_{j\alpha }\}=0,\; 
\mathbf{E}\{X_{j\alpha }^{2}\}=1,\;\mathbf{E}\{X_{j\alpha
}^{4}\}=m_{4}<\infty  \label{Xn}
\end{equation} 
with jointly  i.i.d. entries (cf. (\ref{wga})), $b_{n}$ is the $n$ 
-component random vector
\begin{equation}
b^{(n)}=\{b_{j}\}_{j=1}^{n},\;\mathbf{E}\{b_{j}\}=0,\;\mathbf{E} 
\{b_{j}^{2}\}=\sigma _{b}^{2}  \label{b}
\end{equation} 
with jointly  i.i.d. components (cf. (\ref{bga})) and for all $n$ the matrix $X_{n}$
and the vector $b_{n}$ viewed as defined on the same probability space 
\begin{equation}
\Omega _{X,b}=\Omega _{X}\times \Omega _{b},  \label{oxb}
\end{equation} 
where $\Omega _{X}$ and $\Omega _{b}$ are generated by the analogs of (\ref{xinf}) and (\ref 
{binf});

\smallskip (c) $K_{n}$ is the diagonal random matrix
\begin{equation}
K_{n}=\{\delta _{jk}K_{jn}\}_{j,k=1}^{n},\;K_{jn}=\left( \varphi ^{\prime } 
\Big(n^{-1/2}\sum_{a=1}^{n}X_{j\alpha }x_{\alpha n}+b_{j}\Big)\right) ^{2},
\label{Dn}
\end{equation} 
where $\varphi :\mathbb{R}\rightarrow \mathbb{R}$ is
continuously differentiable, is not identically constant and
such that (cf. (\ref{phi1}))
\begin{equation}
\sup_{x\in \mathbb{R}}|\varphi (x)|=\Phi _{0}<\infty ,\;\sup_{x\in \mathbb{R} 
}|\varphi ^{\prime }(x)|=\Phi _{1}<\infty ,  \label{Phi}
\end{equation}
$x_{n}=\{x_{\alpha n}\}_{\alpha =1}^{n}$ is a collection of real numbers
such that there exists the limit 
\begin{equation}
q=\lim_{n\rightarrow \infty }q_{n}>\sigma
_{b}^{2}>0,\;q_{n}=n^{-1}\sum_{\alpha =1}^{n}(x_{\alpha n})^{2}+\sigma
_{b}^{2}  \label{qqn}
\end{equation}
and
\begin{equation}
\lim_{n\rightarrow \infty }n^{-2}\sum_{\alpha =1}^{n}(x_{\alpha n})^{4}=0.
\label{xbou}
\end{equation}

Then the Normalized Counting Measure (NCM) $\nu _{\mathcal{M}_{n}}$ of $ 
\mathcal{M}_{n}$ converges weakly with probability 1 in $\Omega _{X,b}$ of ( 
\ref{oxb}) to a non-random measure $\nu _{\mathcal{M}}$, such that

\begin{equation}
\nu _{\mathcal{M}}(\mathbb{R_+})=1,  \label{numr1}
\end{equation} 
and that its Stieltjes transform $f_{\mathcal{M}}$ can be obtained from the
formulas 
\begin{align}
f_{\mathcal{M}}(z):& =\int_{0}^{\infty }\frac{\nu _{\mathcal{M}}(d\lambda )}{ 
\lambda -z}  \notag \\
& =\int_{0}^{\infty }\frac{\nu _{R}(d\lambda )}{k(z)\lambda -z} 
=-z^{-1}+z^{-1}h(z)k(z), \; z \in \mathbb{C} \setminus \mathbb{R}_+, \label{fhk}
\end{align} 
where the pair ($h,k$) is the unique solution of the system of functional
equations 
\begin{equation}
h(z)=\int_{0}^{\infty }\frac{\lambda \nu _{R}(d\lambda )}{k(z)\lambda -z}, \; z \in \mathbb{C} \setminus \mathbb{R}_+
\label{hk}
\end{equation} 

\begin{equation}
k(z)=\int_{0}^{\infty }\frac{\lambda \nu _{K}(d\lambda )}{h(z)\lambda +1}, \; z \in \mathbb{C} \setminus \mathbb{R}_+,
\label{kh}
\end{equation} 
in which $\nu _{R}$ is defined in (\ref{nur}), and                   




\begin{equation}
\nu _{K}(\Delta )=\mathbf{P}\Big\{\big(\varphi ^{\prime }((q-\sigma
_{b}^{2})^{1/2}\gamma +b_{1})\big)^{2}\in \Delta \Big\},\;\Delta \in \mathbb{R},
\label{nuka}
\end{equation} 
where $q$ is given by (\ref{qqn}), $\gamma $ is the standard Gaussian random
variable and we are looking for a solution of (\ref{hk}) -- (\ref{kh})

in the class of pairs $(h,k)$ of functions analytic outside
the closed positive semi-axis, continuous and positive on the negative semi-axis
and
such that\begin{equation}
\Im h(z)\Im z>0,\;\Im z\neq 0;\;\sup_{\xi \geq 1}\xi h(-\xi )\in (0,\infty ).
\label{hcond}
\end{equation}

\label{c:conv} Let $\nu _{K},\;\nu _{R}$ and $\nu _{\mathcal{M}}$ be the
probability measures (non-negative measures of the total mass 1)
entering (\ref{fhk}) -- (\ref{kh}) and $m_{K},\;m_{R}$ and $m_{\mathcal{M}}$
be their moment generating functions (see (\ref{mgen}) -- (\ref{stmg})).
Then their functional inverses $z_{K},\;z_{R}$ and $z_{\mathcal{M}}$ are
related as follows
\begin{equation}
z_{\mathcal{M}}(m)=z_{K}(m)z_{R}(m)m^{-1},  \label{mconv}
\end{equation} 
or, writing
\begin{equation}
z_{A}(m)=m\sigma _{A}(m),\;A=K,R,\mathcal{M,} \label{siz}
\end{equation} 
we obtain the simple "algebraic" form
\begin{equation}
\sigma _{\mathcal{M}}(m)=\sigma _{K}(m)\sigma _{R}(m)  \label{sconv}
\end{equation}
of the operation $\diamond$ of (\ref{opdia}).

t follows from (\ref{hk}) -- (\ref{kh}) and (\ref{stmg}) that 
\begin{align}
& m_{K}(-h(z))=-h(z)k(z),\;m_{R}(k(z)z^{-1})=-h(z)k(z),  \notag \\
& \hspace{1cm}m_{\mathcal{M}}(z^{-1})=-h(z)k(z).  \label{rels}
\end{align} 
Now the first and the third relations (\ref{rels}) yield $ 
m_{K}(-h(z^{-1}))=m_{\mathcal{M}}(z)$, hence $z_{K}(m)=-h(z_{\mathcal{M} 
}^{-1}(m))$, and then the second and the third relations yield $ 
m_{R}(k(z^{-1})z)=m_{\mathcal{M}}(z)$, hence $z_{R}(\mu )=k(z_{\mathcal{M} 
}^{-1}(m))z_{\mathcal{M}}(m)$. Multiplying these two relations and using
once more the third relation in (\ref{rels}), we obtain 
\begin{equation*}
z_{K}(m)z_{R}(m)=-k(z_{\mathcal{M}}^{-1}(m))h(z_{\mathcal{M}}^{-1}(m))z_{ 
\mathcal{M}}(m)=z_{\mathcal{M}}(m)m
\end{equation*} 
and (\ref{mconv}) -- (\ref{sconv}) follows.

\label{r:diamond}  In the case of rectangular matrices $X_{n}$ in (\ref{mncal} 
), described in Remark \ref{r:rra} (ii), the analogs of (\ref{mconv}) and ( 
\ref{sconv}) are
\begin{equation}
z_{\mathcal{M}}(m)=z_{K}(cm)z_{R}(cm)m^{-1},\;\sigma _{\mathcal{M} 
}(m)=c^{2}\sigma _{K}(cm)\sigma _{R}(cm).  \label{rect}
\end{equation}

\label{t:main} Let $M_{n}^{L}$ be the random matrix (\ref{JJM}) defined by ( 
\ref{rec}) -- (\ref{D}) and (\ref{nequ}), where the weights $ 
\{W^{l}\}_{l=1}=\{n^{-1/2}X^{l}\}_{l=1}$ and biases $\{b^{l}\}_{l=1}$ are
i.i.d. in $l$ with i.i.d. entries and components satisfying (\ref{bga}) -- ( 
\ref{wga}) and the input vector $x^{0}$ (\ref{x0}) (deterministic or random)
is such that there exists a finite limit 
\begin{equation}
q^{1}:=\lim_{n\rightarrow \infty }q_{n}^{1}>\sigma
_{b}^{2}>0,\;\;q_{n}^{1}=n^{-1}\sum_{j_{0}=1}^{n}(x_{j_{0}}^{0})^{2}+\sigma
_{b}^{2}  \label{q0}
\end{equation} 
and
\begin{equation}
\lim_{n\rightarrow \infty }n^{-2}\sum_{j_{0}=1}^{n}(x_{j_{0}}^{0})^{4}=0.
\label{qLin}
\end{equation} 
Assume also that the activation function $\varphi $ in (\ref{rec}) is
continuously differentiable, $\varphi ^{\prime }$ is not
zero identically and 
\begin{equation}
\sup_{t\in \mathbb{R}}|\varphi (t)|=:\Phi _{0}<\infty ,\;\sup_{t\in \mathbb{R} 
}|\varphi ^{\prime }(t)|=:\Phi _{1}<\infty .\;\;  \label{phi1}
\end{equation} 
Then the Normalized Counting Measure (NCM) $\nu _{M_{n}^{L}}$ of $M_{n}^{L}$
(see (\ref{ncm})) converges weakly with probability 1 in the probability
space $\Omega _{L}$ of (\ref{oml}) to a non-random limit
\begin{equation}
\nu _{M^{L}}=\lim_{n \to \infty}   \nu _{M^{L}_n},  \label{numl}
\end{equation}
where
\begin{equation}
\nu _{M^{L}}=\nu _{K^{L}}\diamond \cdots \diamond \nu
_{K^{1}},  \label{nucon}
\end{equation} 
the operation "$\diamond $" is defined in (\ref{opdia}) (see also

Remark \ref{r:penn} (ii) Corollary \ref{c:conv} below) and
\begin{equation}
\nu _{K^{l}}(\Delta )=\mathbf{P}\Big\{\big(\varphi ^{\prime }((q^{l}-\sigma
_{b}^{2})^{1/2}\gamma +b_{1})\big)^{2}\in \Delta \Big\},\;\Delta \in \mathbb{R} 
,\;l=1,...,L,  \label{nukal}
\end{equation} 
with the standard Gaussian random variable $\gamma $ and $q^{l}$ determined
by the recurrence
\begin{equation}
q^{l}=\int \varphi ^{2}\Big(\gamma (q^{l-1}-\sigma _{b}^{2})^{1/2}+b\Big) 
\Gamma (d\gamma )F(db),\;l\geq 2,  \label{qlql}
\end{equation} 
where $\Gamma (d\gamma )=(2\pi )^{1/2}e^{-\gamma ^{2}/2}d\gamma $ is the
standard Gaussian measure, $F$ is the probability law of $b_{1}^{l}$ in (\ref 
{bga}) and $q^{1}$ is given by (\ref{q0}).

e prove the theorem by induction in $L$. We have from (\ref{rec}) -- (\ref 
{JJM}) and (\ref{nequ}) with $L=1$ the following $n\times n$ random matrix 
\begin{equation}
M_{n}^{1}=J_{n}^{1}(J_{n}^{1})^{T}=n^{-1}D_{n}^{1}X_{n}^{1}(X_{n}^{1})^{T}D_{n}^{1}.
\label{m1}
\end{equation} 
It is convenient to pass from $M_{n}^{1}$ to the $n\times n$ matrix (see
Remark \ref{r:kgen}) 
\begin{equation}
\mathcal{M} 
_{n}^{1}=(J_{n}^{1})^{T}J_{n}^{1}=n^{-1}(X_{n}^{1})^{T}K_{n}^{1}X_{n}^{1}, 
\;K_{n}^{1}=(D_{n}^{1})^{2}  \label{cm1}
\end{equation} 
which has the same spectrum, hence the same Normalized Counting Measure as $ 
M_{n}^{1}$. The matrix $\mathcal{M}_{n}^{1}$ is a particular case with $ 
S_{n}=\mathbf{1}_{n}$ of matrix (\ref{mncal}) treated in Theorem \ref{t:ind}
above. Since the NCM of $\mathbf{1}_{n}$ is the Dirac measure $\delta _{1}$,
conditions (\ref{r2}) -- (\ref{nur}) of the theorem are evident. Conditions ( 
\ref{qqn}) and (\ref{xbou}) of the theorem are just (\ref{q0}) and (\ref 
{qLin}). It follows then from Corollary \ref{c:conv} that the assertion of
our theorem, i.e., formula (\ref{nucon}) with $q^{1}$ of (\ref{q0}) is valid
for $L=1$.

Consider now the case  where $L=2$ of (\ref{rec}) -- (\ref{JJM}) and (\ref{nequ}):
\begin{equation}
M_{n}^{2}=n^{-1}D_{n}^{2}X_{n}^{2}M_{n}^{1}(X_{n}^{2})^{T}D_{n}^{2}.
\label{m2m1}
\end{equation} 
Since $M_{n}^{1}$ is positive definite, we write
\begin{equation}
M_{n}^{1}=(S_{n}^{1})^{2}  \label{m1s1}
\end{equation} 
with a positive definite $S_{n}^{1}$, hence,
\begin{equation}
M_{n}^{2}=n^{-1}D_{n}^{2}X_{n}^{2}(S_{n}^{1})^{2}(X_{n}^{2})^{T}D_{n}^{2}
\label{mn2}
\end{equation} 
and the corresponding $\mathcal{M}_{n}^{2}$ is
(see Remark \ref{r:kgen})
\begin{equation}
\mathcal{M} 
_{n}^{2}=n^{-1}S_{n}^{1}(X_{n}^{^{2}})^{T}K_{n}^{2}X_{n}^{2}S_{n}^{1}, 
\;K_{n}^{2}=(D_{n}^{2})^{2}.  \label{cm1m2}
\end{equation} 
We observe that $\mathcal{M}_{n}^{2}$ is a particular case of matrix (\ref 
{mncal}) of Theorem \ref{t:ind} with $M_{n}^{1}$ of (\ref{m1s1}) as $ 
R_{n}=(S_{n})^{2}$, $X_{n}^{2}$ as $X_{n}$, $K_{n}^{2}$ as $K_{n}$, $ 
\{x_{j_{1}}^{1}\}_{j_{1}=1}^{n}$ as $\{x_{\alpha n}\}_{\alpha =1}^{n}$, $ 
\Omega _{1}=\Omega ^{1}$ of (\ref{oml}) as $\Omega _{R,x}$ and $\Omega ^{2}$
of (\ref{oml}) as $\Omega _{X,b}$, i.e., the case of the random but\ $ 
\{X_{n}^{2},b^{2}_{n}\}$ -independent $R_{n}$ and $\{x_{\alpha n}\}_{\alpha
=1}^{n}$ in (\ref{mncal}) as described in Remark \ref{r:rra} (i). Let us
check that conditions (\ref{r2}) -- (\ref{nur}) \ and (\ref{qqn}) -- (\ref 
{xbou}) of Theorem \ref{t:ind} are satisfied for $\mathcal{M}_{n}^{2}$ of ( 
\ref{cm1m2}) with probability 1 in the probability space $\Omega
_{1}=\Omega^1$ generated by $\{X_{n}^{1},b_{n}^{1}\}$ for all $n$ and
independent of the space $\Omega ^{2}$ generated by $\{X_{n}^{2},b_{n}^{2}\}$
for all $n$.

To this end we use an important fact on the operator norm of $n\times n$
random matrices with i.i.d. entries satisfying (\ref{wga}). Namely, if $ 
X_{n} $ is a such $n\times n$ matrix, then we have with probability 1
\begin{equation}
\lim_{n\rightarrow \infty }n^{-1/2}||X_{n}||=2,  \label{lin}
\end{equation} 
thus, with the same probability 
\begin{equation}
||X_{n}||\leq Cn^{1/2},\;2 \le C < \infty,\; n \ge n_0,  \label{nox}
\end{equation} 
if $n_0$ is large enough.

For the Gaussian matrices relation (\ref{lin}) has already been known in the
Wigner school of the early 1960th, see \cite{Pa-Sh:11}. It follows in this
case from the orthogonal polynomial representation of the density of the NCM
of $n^{-1}X_{n}X_{n}^{T}$ and the asymptotic formula for the corresponding
orthogonal polynomials. For the modern form of (\ref{lin}),
in particular its validity for random matrices with i.i.d entries of zero
mean and finite fourth moment, see \cite{Ba-Si:00,Ve:18} and references
therein.

We will also need the bound 
\begin{equation}
||K_{n}^{1}||\leq \Phi^{2} _{1},  \label{nok}
\end{equation} 
following from (\ref{D}), (\ref{kan}) and (\ref{phi1}) and valid everywhere
in $\Omega _{1}$ of (\ref{oml}).

Now, by using (\ref{cm1}), (\ref{nox}), (\ref{nok}) and the inequality
\begin{equation}
|\mathrm{Tr}AB|\leq ||A||\mathrm{Tr}B,\;  \label{tab}
\end{equation} 
valid for any matrix $A$ and a positive definite matrix $B$, we obtain with
probability 1 in $\Omega _{1}$ and for sufficiently large $n_{0}$ of (\ref{nok})
\begin{equation*}
n^{-1}\mathrm{Tr}(M_{n}^{1})^{2}=n^{-3}\mathrm{Tr}\mathbb{(} 
K_{n}^{1}X_{n}^{1}(X_{n}^{1})^{T})^{2}\leq (C\Phi _{1})^{4}.
\end{equation*} 
We conclude that $M_{n}^{1}$, which plays here the role of $R_{n}$ of
Theorem \ref{t:ind} and Remark \ref{r:rra} (i) according to (\ref{m1s1}),
satisfies condition (\ref{r2}) with $r_{2}=(C\Phi _{1})^{4}$ and with
probability 1 in our case, i.e., on a certain $\Omega _{11}\subset \Omega
_{1},\;\mathbf{P}(\Omega _{11})=1$.

Next, it follows from the above proof of the theorem for $L=1$, i.e., in
fact, from Theorem \ref{t:ind}, that there exists $\Omega _{12}\subset
\Omega _{1},\;\mathbf{P}(\Omega _{12})=1$ on which the NCM $\nu _{M_{n}^{1}}$
converges weakly to a non-random limit $\nu _{M^{1}}$, hence condition (\ref 
{nur}) is also satisfied with probability 1, i.e., on $\Omega _{12}$.

At last, according to Lemma \ref{l:xlyl} and (\ref{q0}), there exists $ 
\Omega _{13}\subset \Omega _{1},\;\mathbf{P}(\Omega _{13})=1$ on which there
exists
\begin{equation*}
\lim_{n\rightarrow \infty
}n^{-1}\sum_{j_{0}=1}^{n}(x_{j_{0}}^{0})^{2}+\sigma _{b}^{2}=q^{1}>\sigma
_{b}^{2},
\end{equation*} 
and according to (\ref{rec}) and (\ref{phi1}) we have uniformly in $n$: $ 
|x_{j_{1}}^{1}|\leq \Phi _{0},\;j_{1}=1,...,n$, i.e., conditions (\ref{qqn}) and (\ref{qLin})
are also satisfied.

Hence, we can apply Theorem \ref{t:ind}\ on the subspace $\overline{\Omega } 
_{1}=\Omega _{11}\cap \Omega _{12}\cap \Omega _{13}\subset \Omega _{1},\; 
\mathbf{P}(\overline{\Omega }_{1})=1$ where all the conditions of the
theorem are valid, i.e., $\overline{\Omega }_{1}$ plays the role of $\Omega
_{R,x} $ of Remark \ref{r:rra} (i). Then, the theorem implies that for every $ 
\omega _{1}\in \overline{\Omega }_1$ there exists subspace $\overline{ 
\Omega^2}(\omega _{1})$ of the space $\Omega ^{2}$  generated by $ 
\{X_{n}^{2},b_{n}^{2}\}$ for all $n$ and such that $\mathbf{P}(\overline{ 
\Omega^2}(\omega _{1}))=1$ and formulas (\ref{nucon}) -- (\ref{qlql}) are
valid for $L=2$. It follows then from the Fubini theorem that the same is
true on a certain $\overline{\Omega }_{2}\subset \Omega _{2},\;\mathbf{P}( 
\overline{\Omega }_{2})=1$ where $\Omega _{2}$ is defined by (\ref{oml})
with $L=2$.

This proves the theorem for $L=2$. The proof for $L=3,4,\dots$ is analogous,
since (cf. (\ref{mn2}))
\begin{equation}
M_{n}^{l+1}=n^{-1}D_{n}^{l+1}X_{n}^{l+1}M_{n}^{l}(X_{n}^{l+1})^{T}D_{n}^{l+1},\;l\geq 2.
\label{mlml1}
\end{equation} 
In particular, we have with probability 1 on $\Omega _{l}$ of (\ref{oml})
for $M_{n}^{l}$ playing the role of $R_{n}$ of Theorem \ref{t:ind} on the $l$ 
th step of the inductive procedure (cf. (\ref{r2}))
\begin{equation*}
n^{-1}\mathrm{Tr}(M^{l})^{2}\leq (C\Phi _{1})^{4l},\;l\geq 2.
\end{equation*}
If $x_0$ is random, then it is necessary to follow the argument
given in Remark \ref{r:penn} (iii).

\label{p:facts} Let $A$ and $B$ be $n\times n$ real symmetric matrices and $L_{Y}$
be the rank one real symmetric matrix corresponding to the vector $Y=\{Y_{\alpha
}\}_{\alpha =1}^{n}\in \mathbb{C}^{n}$, i.e., 
\begin{equation}
L_{Y}=\{L_{\alpha \beta }\}_{\alpha,\beta=1}^n, \;L_{\alpha \beta
}=Y_{\alpha }Y_{\beta }.  \label{L}
\end{equation} 
We have:

(i)
\begin{equation}
\mathrm{Tr}AL_{Y}=(AY,Y)  \label{tral}
\end{equation}

(ii) if 
\begin{equation}
G_{A}(z)=(A-z)^{-1},\;G_{B}(z)=(B-z)^{-1},\;\Im z\neq 0,  \label{ress}
\end{equation} 
are the resolvents of $A$ and $B$, then the resolvent identity 
\begin{equation}
G_{A}(z)=G_{B}(z)-G_{A}(z)(A-B)G_{B}(z),\;\Im z\neq 0  \label{resi}
\end{equation} 
is valid;

(iii) if $K$ is a real number and
\begin{equation}
A=B+KL_{Y},  \label{r11}
\end{equation} 
where $L_{Y}$ is given by (\ref{L}), then the rank one perturbation formula 
\begin{equation}
G_{A}(z)=G_{B}(z)-\frac{K}{1+K(G_{B}(z)Y,Y)}G_{B}(z)L_{Y}G_{B}(z),\;\Im
z\neq 0  \label{r12}
\end{equation} 
is valid, if $C$ is one more $n\times n$ matrix (not necessarily hermitian), then 
\begin{equation}
n^{-1}\mathrm{Tr}G_{A}(z)C-n^{  -1}\mathrm{Tr}G_{B}(z)C=-\frac{1}{n}\cdot \frac{ 
K(G_{B}(z)CG_{B}(z)Y,Y)}{1+K(G_{B}(z)Y,Y)}  \label{tr12}
\end{equation} 
and if $B$ is positive definite and $K\geq 0$, then
\begin{equation}
|n^{-1}\mathrm{Tr}G_{A}(-\xi )C-n^{-1}\mathrm{Tr}G_{B}(-\xi )C|\leq
||C||/n\xi, \;\xi >0;  \label{troc}
\end{equation} 
(iv) if $X=\{X_{\alpha }\}_{\alpha =1}^{n}\in \mathbb{R}^{n}$ is a random
vector with jointly independent and identically distributed real components and (cf. (\ref 
{wga}) and (\ref{wm4})) 
\begin{equation}
\mathbf{E}\{X_{\alpha }\}=0,\;\mathbf{E}\{X_{\alpha }^{2}\}=1,\;\mathbf{E} 
\{X_{\alpha }^{4}\}=m_{4}<\infty ,  \label{m4}
\end{equation} 
where $\mathbf{E}\{\dots\}$ denotes the corresponding expectation, and
\begin{equation}
Y=n^{-1/2}SX,  \label{ysx}
\end{equation} 
with a $X$-independent $n\times n$ real symmetric matrix $S$, then
\begin{equation}
\mathbf{E}\{L_{Y}\}=n^{-1}R,\;R=S^{2}  \label{eys}
\end{equation} 
and if
\begin{equation}
a=(CY,Y),  \label{a}
\end{equation} 
is a quadratic form with a $X$-independent and not necessarily
hermitian $C$, then
\begin{equation}
\mathbf{E}\{a\}=n^{-1}\mathrm{Tr}\,CR=n^{-1}\mathrm{Tr}\,C_{S},\;C_{S}=SCS
\label{ea}
\end{equation} 
and 






\begin{equation}
\mathbf{Var}\{a\}:=\mathbf{E}\{|a|^{2}\}-|\mathbf{E}\{a\}|^{2}\leq \mu \; 
\mathrm{Tr}\,C_{S}C_{S}^{\ast }/n^{2},\;\mu =m_{4}+1,  \label{exa}
\end{equation} 
where $C^{\ast }$ is the hermitian conjugate of $C$ (recall that $ m_4 \in [1, \infty)$ in view of (\ref{m4})).

ssertions (i) and (ii) are elementary.

(iii). To obtain (\ref{r12}) we use (\ref{resi}) with $A$ and $B$ of (\ref 
{r11}) to write the formula 
\begin{equation}
G_{A}(z)=G_{B}(z)-KG_{A}(z)LG_{B}(z).  \label{resi1}
\end{equation} 
Multiplying it by $L$ of (\ref{L}) from the right and using $ 
LG_{B}(z)L=(G_{B}(z)Y,Y)L$, we get
\begin{equation}
G_{A}(z)L=(1+K(G_{B}(z)Y,Y))^{-1}G_{B}(z)L.  \label{resi2}
\end{equation} 
Plugging this into the r.h.s. of (\ref{resi1}), we obtain (\ref{r12}) and
then (\ref{tr12}).

Note that the r.h.s. of (\ref{r12}) and (\ref{tr12}) are well defined for $ 
\Im z\neq 0$. Indeed, it follows from (\ref{resi}) with $A-z$ as $A$ and \ $ 
A-z^{\ast }$as $B$\ that
\begin{equation*}
\Im G(z)=(2i)^{-1}(G-G^{\ast })=\Im z\ G^{\ast }(z)G(z),
\end{equation*} 
thus
\begin{equation*}
|1+K(G_{B}(z)Y,Y)|\geq |K\Im (G_{B}(z)Y,Y)|=|K|\ |\Im z|\
||G_{B}(z)Y||^{2}>0,\ \Im z\neq 0.
\end{equation*} 
To get (\ref{troc}) we take into account that $K\geq 0$ and $(G_{B}(-\xi
)Y,Y)\geq 0$, since $B$, hence, $G_{B}(-\xi )$ is positive definite. This yields
the following bound for the r.h.s. of (\ref{tr12})
\begin{equation*}
||C||\,||G_{B}(-\xi )Y)||^{2}/(G_{B}(-\xi )Y,Y)=||C||(G_{B}^{2}(-\xi
)Y,Y)/(G_{B}(-\xi )Y,Y)
\end{equation*} 
implying
\begin{align*}
& (G_{B}(-\xi )Y,Y)=(G_{B}^{-1}(-\xi )G_{B}^{2}(-\xi
)Y,Y)=((B+\xi )G_{B}^{2}(-\xi )Y,Y) \\
& \hspace{1.5cm}=(G_{B}(-\xi )BG_{B}(-\xi )Y,Y)+\xi (G_{B}^{2}(-\xi
)Y,Y)\geq \xi (G_{B}^{2}(-\xi )Y,Y).
\end{align*} 

(iv) We use the formulas (see (\ref{m4})) 
\begin{align*}
\mathbf{E}\{X_{\alpha _{1}}X_{\alpha _{2}}\} =\delta _{\alpha_{1}\alpha_{2}}, \\
\mathbf{E}\{X_{\alpha _{1}}X_{\alpha _{2}}X_{\alpha _{3}}X_{\alpha _{4}}\}
&=\delta _{\alpha_{1}\alpha_{2}}\delta _{\alpha_{3}\alpha_{4}}+\delta _{\alpha_{1}\alpha_{3}}\delta
_{\alpha_{2}\alpha_{4}}
\\&\hspace{0.3cm}+\delta _{\alpha_{1}\alpha_{4}}\delta _{\alpha_{2}\alpha_{3}}+(m_{4}-3)\delta
_{\alpha_{1}\alpha_{2}}\delta _{\alpha_{1}\alpha_{3}}\delta _{\alpha_{1}\alpha_{4}}.
\end{align*} 
The first line above, (\ref{L}) and (\ref{ysx}) yields (\ref{eys})\ and
(\ref{ea}), while the second line implies 
\begin{eqnarray*}
\mathbf{E}\{|a|^{2}\} &=&n^{-2}|\mathrm{Tr\,}C_{S}|^{2}+n^{-2}\sum_{\alpha
\neq \beta =1}^{n}|(C_{S})_{\alpha \beta }|^{2} \\
&&+n^{-2}\sum_{\alpha \neq \beta =1}^{n}(C_{S})_{\alpha \beta
}(C_{S})_{\beta \alpha }^{\ast }+(m_{4}-1)n^{-2}\sum_{\alpha
=1}^{n}|(C_{S})_{\alpha \alpha }|^{2}.
\end{eqnarray*} 
The sums of the r.h.s. are bounded by 
\begin{equation*}
n^{-2}\sum_{\alpha \neq \beta =1}^{n}|(C_{S})_{\alpha \beta }|^{2}=n^{-2} 
\mathrm{Tr\,}C_{S}C_{S}^{\ast }
\end{equation*} 
and $m_{4}\geq 1$ in view of (\ref{m4}). This leads (\ref{exa}).

e begin with using Lemma \ref{l:mart} (i) below implying that the fluctuations (\ref{mnu4}) of $\nu _{ 
\mathcal{M}_{n}}$ vanish sufficiently fast as $n\rightarrow \infty $. This
and the Borel-Cantelli lemma imply that
\[
\lim_{n \to \infty} |\nu_{\mathcal{M}_{n}}(\Delta)-\mathbf{E}\{\nu _{\mathcal{M}_{n}}(\Delta)\}|=0
\]
with probability 1, hence reduce the proof of the theorem to
the proof of the weak convergence of the expectation
\begin{equation}
\overline{\nu }_{\mathcal{M}_{n}}:=\mathbf{E}\{\nu _{\mathcal{M}_{n}}\}
\label{numc}
\end{equation} 
of $\nu _{\mathcal{M}_{n}}$ to the limit $\nu _{\mathcal{M}}$ whose
Stieltjes transform is given by (\ref{fhk}) -- (\ref{hcond}). Since $\mathcal{M} 
_{n}$ is positive definite, hence, its spectrum belongs to the closed positive
semiaxis $\mathbb{R}_{+}$ for all $n$, it suffices to prove the tightness of the
sequence of measures $\{\overline{\nu }_{\mathcal{M}_{n}}\}_{n}$ and the
pointwise convergence on a set of positive Lebesgue measure in $\mathbb{C} 
\setminus \mathbb{R}_{+}$ of their Stieltjes transforms (cf. (\ref{stm}))
\begin{equation}
f_{\mathcal{M}_{n}}(z):=\int_{0}^{\infty }\frac{\overline{\nu }_{\mathcal{M} 
_{n}}(d\lambda )}{\lambda -z}, \;  \mathbb{C} 
\setminus \mathbb{R}_{+} \label{fmnc}
\end{equation} 
to the limit satisfying (\ref{fhk}) -- (\ref{hcond}), see, e.g. \cite 
{Pa-Sh:11}, Proposition 2.1.2.

The tightness is guaranteed by the uniform in $n$ bound for 
\begin{equation}
\mu _{n}^{(1)}:=\int_{0}^{\infty }\lambda \overline{\nu }_{\mathcal{M} 
_{n}}(d\lambda ),  \label{mom}
\end{equation} 
since for any $T>0$ we have for the tail of $ \overline{\nu }_{\mathcal{M} 
_{n}}$
\[
\int_T^\infty \overline{\nu }_{\mathcal{M} 
_{n}}(d\lambda ) \le T^{-1}\int_{T}^{\infty }\lambda \overline{\nu }_{\mathcal{M} 
_{n}}(d\lambda )\le \mu _{n}^{(1)}/T.
\]
According to the definition of the NCM (see, e.g. (\ref{ncm})), spectral
theorem and (\ref{mncal}), we have
\begin{equation*}
\mu _{n}^{(1)}=\mathbf{E}\{n^{-1}\mathrm{Tr}\,\mathcal{M}_{n}\}=\mathbf{E} 
\{n^{-2}\mathrm{Tr}\,X_{n}R_{n}X_{n}^{T}K_{n}\}
\end{equation*} 
and then (\ref{tab}), (\ref{r2}) -- (\ref{Xn}) and (\ref{Dn}) -- (\ref{Phi})
yield 
\begin{equation}
\mu _{n}^{(1)}\leq n^{-2}\Phi _{1}^{2}\mathbf{E}\{\mathrm{Tr}\, 
X_{n}R_{n}X_{n}^{T}\}=\Phi _{1}^{2}n^{-1}\mathrm{Tr}\,R_{n}\leq
r_{2}^{1/2}\Phi _{1}^{2},  \label{tim}
\end{equation} 
where we used the inequality $n^{-1}\mathrm{Tr}\,R_{n} \le (n^{-1}\mathrm{Tr}\,R_{n}^2)^{1/2}$ to obtain the r.h.s. bound. This implies the tightness of $\{\overline{\nu }_{\mathcal{M}_{n}}\}_{n}$
and reduces the proof of the theorem to the proof of pointwise in $\mathbb{C} 
\setminus \mathbb{R}_{+}$ convergence of (\ref{fmnc}) to the limit
determined by (\ref{fhk}) -- (\ref{kh}).

The above argument, reducing the analysis of the large size behavior of the
eigenvalue distribution of random matrices to that of the expectation of the Stieltjes transform of the distribution, is widely used in random matrix
theory (see \cite{Pa-Sh:11}, Chapters 3, 7, 18 and 19), in particular, while
dealing with the sample covariance matrices. However, the matrix $\mathcal{M} 
_{n}$ of (\ref{mncal}) differs essentially from the sample covariance
matrices, since the "central" matrix $K_{n}$ of (\ref{Dn}) is random and
dependent on $X_{n}$ (the data matrix according to statistics), while in the
sample covariance matrix the analog of $K_{n}$ is either deterministic or
random but independent of $X_{n}$. Nevertheless, we show that in our case of
the $X_{n}$-dependent $K_{n}$ of (\ref{Dn}) it suffices to follow
essentially the proof for $X_{n}$-independent analogs of $K_{n}$, which
dates back to \cite{Ma-Pa:67,Pa:72} and has been largely extended and
used afterwards, see, e.g. \cite{Pa-Sh:11,Ak-Co:11,Ba-Si:00,Gi:12}.

We outline first the scheme of the proof of the theorem. Write (\ref{mncal}) as
\begin{equation}
\mathcal{M}_{n}=\sum_{j=1}^{n}K_{jn}L_{jn},  \label{mnr1}
\end{equation} 
where $K_{jn}$ are given by (\ref{Dn}) and
\begin{equation}
L_{jn}=L_{Y_{j}}  \label{lljn}
\end{equation} 
is the rank-one matrix (\ref{L}) corresponding to the random vector (cf. ( 
\ref{ysx}))
\begin{equation}
Y_{j}=\{n^{-1/2}(S_{n}X_{n}^{T})_{j\alpha }\}_{\alpha
=1}^{n}=n^{-1/2}S_{n}X_{j},\;X_{j}=\{X_{j\alpha }\}_{\alpha =1}^{n},
\label{Yj}
\end{equation} 
i.e., $X_{j}$ is the $j$th row of the random matrix (\ref{Xn}), thus the
collection $\{X_{j}\}_{j=1}^{n}$ consists of i.i.d. random vectors
satisfying (\ref{m4}).

It follows from the definition of the Normalized Counting Measure (see (\ref 
{ncm})) and the spectral theorem for the resolvent 
\begin{equation}
G_{\mathcal{M}_{n}}(z)=(\mathcal{M}_{n}-z)^{-1}  \label{gmnc}
\end{equation} 
of $\mathcal{M}_{n}$ that
\begin{equation}
f_{\mathcal{M}_{n}}(z)=\mathbf{E}\{n^{-1}\mathrm{Tr}\,G_{\mathcal{M}_{n}}(z)\}.
\label{fntr}
\end{equation} 
Hence, we have to deal with $G_{\mathcal{M}_{n}}(z)$.

By using the resolvent
identity (\ref{resi}) for $A=\mathcal{M}_{n}$ and $B=0$, we obtain for (\ref 
{gmnc}) in view of (\ref{mnr1}) 
\begin{equation}
G(z)=-z^{-1}+z^{-1}\sum_{j=1}^{n}K_{j}G(z)L_{j},  \label{cg1}
\end{equation} 
and we omit here and below the subindex $\mathcal{M}_{n}$ in the resolvent ( 
\ref{gmnc}) as well as the subindex $n$                      
in many instances below where this does no lead to confusion.

Next, we choose in (\ref{r12}) 
\begin{equation}
A=\mathcal{M}_{n},\;B=\mathcal{M}_{n}^{(j)}:=\mathcal{M}_{n}-K_{j}L_{j}
\label{mmj}
\end{equation} 
and use (\ref{resi2})

to obtain
\begin{equation}
G(z)L_j=G_{j}(z)L_j(1+K_{j}a_{j}(z))^{-1},\;a_{j}(z):=(G_{j}(z)Y_{j},Y_{j}),
\label{ggj}
\end{equation} 
where
\begin{equation}
G_{j}(z):=(\mathcal{M}_{n}^{(j)}-z)^{-1}  \label{cgj}
\end{equation} 
and $Y_{j}$ is defined in (\ref{Yj}).
Plugging (\ref{ggj}) into (\ref{cg1}), we obtain our basic starting formula 
\begin{equation}
G(z)=-z^{-1}+z^{-1}\sum_{j=1}^{n}\frac{K_{j}}{(1+K_{j}a_{j}(z))} 
G_{j}(z)L_{j}  \label{cg20}
\end{equation}
which we are going to convert into the "prelimit" version of the
system (\ref{fhk}) -- (\ref{kh})                                 


plus error terms vanishing as $n\rightarrow \infty $.

It follows from (\ref{fntr}) that we are allowed to make any modification of
(\ref{cg20}) provided that the corresponding error term $\mathcal{E}_n$
satisfies
\begin{equation}
\mathbf{E}\{n^{-1}\mathrm{Tr}\,\mathcal{E}_{n}\}=o(1),\;n\rightarrow \infty .
\label{err}
\end{equation} 
Denote $\mathbf{E}_{j}\{...\}$ the operation of  expectation conditioned on $\{X_k\}_{k \neq j}$

and use:

(i) (\ref{m4}) -- (\ref{exa}) and (\ref{Yj}) to
replace the random quadratic form  $(C Y_{j},Y_{j})$

with a $Y_{j}$ 
-independent matrix $C_{}$ by
\begin{equation}
\mathbf{E}_{j}\{(CY_{j},Y_{j})\}=n^{-1}\mathbf{E}_{j}\{(C_{S}X_{j},X_{j}) 
\}=n^{-1}\mathrm{Tr}\,CR;  \label{exfj}
\end{equation}

(ii) (\ref{tr12}) -- (\ref{troc}) to replace
$n^{-1}\mathrm{Tr}G_{j}(z)C$ with a $Y_{j}$ 
-independent $C$ by $n^{-1}\mathrm{Tr}\,G(z)C$;



(iii) Lemma \ref{l:mart} to replace the random variable $n^{-1}\mathrm{Tr}\, 
G(z)C$ with a $Y_{j}$ 
-independent matrix $C$ by the expectation $\mathbf{E}\{n^{-1} 
\mathrm{Tr}\,G(z)C\}$.

We will  apply then:  (i) with $C=G_{j}$ to replace $a_{j}(z)$ of (\ref{ggj})
by
\begin{equation}
h_{jn}(z)=n^{-1}\mathrm{Tr}\,RG_{j}(z),  \label{hj}
\end{equation} 
 (ii) with $C=R$ to replace $h_{jn}(z)$ by
$h_{n}(z)$ and then
(iii) with $C=R$ to replace $h_{n}(z)$ by $\overline{h_{n}}(z)$, where 
\begin{equation}
h_{n}(z)=n^{-1}\mathrm{Tr}\,RG(z)=n^{-1}\mathrm{Tr}\,SG(z)S,\;\; \overline{h_{n}} 
(z)=\mathbf{E}\{h_{n}(z)\}.  \label{hns}
\end{equation} 
As a result, we can replace $(1+K_{j}a_{j}(z))$ by $(1+K_{j}\overline{h_{n}} 
(z))$ in the r.h.s. of (\ref{cg20}), see Lemma \ref{l:dif} for details.

Likewise, we can replace $L_{j}$ in (\ref 
{cg20}) by its expectation $n^{-1}R$ by using (i)
and then replace $G_{j}(z)$ by $G(z)$ by using (ii) to convert (\ref 
{cg20}) into 
\begin{equation}
G(z)=-z^{-1}+z^{-1}\overline{k}_{n}(z)G(z)R+T_{1}(z),  \label{cg30}
\end{equation} 
where 
\begin{equation}
k_{n}(z)=\frac{1}{n}\sum_{j=1}^{n}\frac{K_{j}}{1+K_{j}\overline{h}_{n}(z)},\; 
\overline{k}_{n}(z)=\mathbf{E}\{k_{n}(z)\}  \label{kns}
\end{equation} 
and 
\begin{equation}
T_{1}(z)=z^{-1}\sum_{j=1}^{n}\frac{K_{j}}{1+K_{j}a_{j}(z)} 
G_{j}(z)L_{j}-z^{-1}\overline{k}_{n}(z)G(z)R.  \label{ct10}
\end{equation}
is the error term.

Applying to (\ref{cg30}) the operation $\mathbf{E}\{n^{-1}\mathrm{Tr\;}\dots\}$
and taking into account (\ref{fntr}) and (\ref{hns}), we get 
\begin{equation}
f_{\mathcal{M}_{n}}(z)=-z^{-1}+z^{-1}\overline{k}_{n}(z)\overline{h} 
_{n}(z)+t_{1n},  \label{fhkn}
\end{equation} 
where 
\begin{equation}
t_{1n}(z)=\mathbf{E}\{n^{-1}\mathrm{Tr}\, T_{1}(z)\},  \label{t10}
\end{equation} 
i.e., a "prelimit" version of (\ref{fhk}) with the error term $t_{1n}$, cf. ( 
\ref{err}).

Next, we have from (\ref{cg30}) 
\begin{equation}
G(z)=\mathcal{G}(z)+zT_{1}\mathcal{G}(z),\;\mathcal{G}(z)=(\overline{k} 
_{n}(z)R-z)^{-1}.  \label{cg40}
\end{equation} 
Multiplying the formula by $R$, applying to the result the operation $ 
\mathbf{E}\{n^{-1}\mathrm{Tr\;}...\}$ and using the fact that $R$ of (\ref 
{r2}), hence, $\mathcal{G}$ are independent of $X_n$ of (\ref{Xn}), we obtain in view of (\ref{hns}) 
\begin{equation}
\overline{h}_{n}(z)=\int_{0}^{\infty }\frac{\lambda \nu _{R_{n}}(d\lambda )}{ 
\lambda \overline{k}_{n}(z)-z}+t_{2n},  \label{hkn}
\end{equation} 
where $\nu _{R_{n}}$ is the Normalized Counting Measure of $R_{n}$ defined
in (\ref{nur}). This is a "prelimit" version of (\ref{hk}) with the error
term (cf. (\ref{err}) and (\ref{t10}))
\begin{equation}
t_{2n}(z)=-z\mathbf{E}\{n^{-1}\mathrm{Tr}\, T_{1}\mathcal{G}(z)R\}.  \label{t20}
\end{equation} 
At last, observing that according to the conditions of the theorem (see (\ref 
{Xn}), (\ref{bl}) and (\ref{Dn})) $\{K_{j}\}_{j=1}^{n}$ are independent
identically distributed (and, possibly, $n$-dependent) random variables, we
obtain from (\ref{kns}) the "prelimit version" 
\begin{equation}
\overline{k}_{n}(z)=\int_{0}^{\infty }\frac{\lambda \overline{\nu } 
_{K_{n}}(d\lambda )}{\lambda \overline{h}_{n}(z)+1}  \label{khn}
\end{equation} 
of (\ref{kh}) in which $\overline{\nu }_{K_{n}}$ is the probability law of
(see (\ref{Dn}))
\begin{equation}
K_{jn}=(\varphi ^{\prime }(\eta _{jn}+b_{j}))^{2},\;\eta
_{jn}=n^{-1/2}\sum_{\alpha =1}^{n}X_{j\alpha }x_{\alpha n}.  \label{nukn0}
\end{equation} 
Having obtained semi-heuristically relations (\ref{fhkn}), (\ref{hkn}) and ( 
\ref{khn}), we pass now to their rigorous derivation, i.e., to the proof
that the remainders $t_{1n}$ of (\ref{t10}) and $t_{2n}$ of (\ref{t20})
vanish in the limit $n\rightarrow \infty $ and that $f_{\mathcal{M}_{n}}$, $ 
\overline{h}_{n}$ and $\overline{k}_{n}$ converge to a solution of (\ref{fhk} 
) -- (\ref{kh}).

We will deal first with the $n \to \infty$ limit in (\ref{fhkn}), (\ref{khn})
and (\ref{hkn}) assuming that $t_{1n}$ and $t_{2n}$ vanish as $n\rightarrow
\infty $. In fact, the limit is a version of that widely used in random
matrix theory, see, e.g. \cite{Pa-Sh:11}. Thus, we just outline the
procedure.

According to (\ref{fmnc}) $f_{\mathcal{M}_{n}}$ is analytic in $\mathbb{C} 
\setminus \mathbb{R}_{+}$ for every $n$. Thus, by Vitali's theorem on the convergence of analytic functions, it suffices to study the limiting properties of the sequence $\{f_{\mathcal{M}_{n}}\}_{n}$ for $z$
varying in a closed interval of the open negative semiaxis 
\begin{equation}
I_{-}=\{z\in \mathbb{C}:z=-\xi ,\;0<\xi _{-}\leq \xi \leq \xi _{+}<\infty \},
\label{imi}
\end{equation} 
where $\xi_\pm$ do not depend on $n$.

Furthermore, since $\mathcal{M}_{n}$ of (\ref{mncal}) and $\mathcal{M} 
_{n}^{(j)}$ of (\ref{mmj}) are positive definite, their resolvents $G(z)$
and $G_{j}(z )$ for $z=-\xi \in I_{-}$ are also positive definite, thus
\begin{equation}
||G(-\xi )||\leq 1/\xi ,\;||G_{j}(-\xi )||\leq 1/\xi,  \; \;\xi >0,  \label{nors}
\end{equation}
and we have for $a_{j}$ of (\ref{ggj})
\begin{equation}
a_{j}(-\xi )\geq 0,\;\xi >0.  \label{aj}
\end{equation} 
Besides, we have from (\ref{Dn}) and (\ref{Phi}) 
\begin{equation}
0\leq K_{j}\leq \Phi _{1}^{2}.  \label{Kj}
\end{equation} 
Thus, $1+K_{j}a_{j}(-\xi )\geq 1$ and (\ref{ggj}) is well defined for $\xi
>0$.

It follows from  (\ref{hns}),  spectral theorem for $\mathcal{M}_{n}$ and (\ref{r2}) that
if $\{\lambda_\alpha\}_\alpha$ and $\{\psi_\alpha\}_\alpha$ are the eigenvalues and the eigenvectors of $\mathcal{M}_n$, then
\begin{align}
&\hspace{0cm} h_n(z)=\int_0^\infty \frac{\mu_n (d \lambda)}{\lambda-z}, \; z \in \mathbb{C} \setminus \mathbb{R}_+,
\notag
\\&\hspace{0.5cm}  \mu_n =n^{-1} \sum_{\alpha} \delta_{\lambda_\alpha} (R\psi_\alpha,\psi_\alpha), \;  \notag
\\&\hspace{-1cm} 0<\mu_n (\mathbb{R}_+)=n^{-1} \sum_{\alpha}(R\psi_\alpha,\psi_\alpha)=n^{-1}\mathrm{Tr}\, R \le r_2^{1/2},\label{hrep}
\end{align}
where we took into account that $R$ is positive defined and used Schwarz inequality for traces. This implies that $h_n$ is analytic in $\mathbb{C} \setminus \mathbb{R}_+$ and
\begin{equation}\label{hnev}
\Im h_n(z)  \Im z =\int_0^\infty \frac{\mu_n (d \lambda)}{|\lambda-z|^2}>0, \; \Im z \neq 0.
\end{equation}
In particular, the function $\overline{k}_n$ of (\ref{kns}) is also analytic in $\mathbb{C} \setminus \mathbb{R}_+$.








It follows also from the above and (\ref{fmnc}) that


\begin{equation}
0<f_{\mathcal{M}_{n}}(-\xi )\leq 1/\xi ,\;\;0<\overline{h}_{n}(-\xi )\leq
r_{2}^{1/2}/\xi ,\;\; 0<\overline{k}_{n}(-\xi )\leq 1,\;\;\xi >0.
\label{pos}
\end{equation} 
Moreover, since the sequences $\{f_{\mathcal{M}_{n}}\}_n, \; \{\overline{h}_{n}\}_n$
and $\{\overline{k}_{n}\}_n$ are real analytic on $I_-$ of (\ref{imi}), there exists
a subsequence $n_{j}\rightarrow \infty $ such that $\{f_{\mathcal{M} 
_{n_{j}}}\},\{\overline{h}_{n_{j}}\}$ and $\{\overline{k}_{n_{j}}\}$
converge uniformly on (\ref{imi}) to certain limits $f_{\mathcal{M}},h$ and $ 
k$ analytic in $\mathbb{C}\setminus \mathbb{R}_{+}$. This allows us to carry
out the limit along $n_{j}\rightarrow \infty $ in the second term in the
r.h.s. of (\ref{fhkn}) and to obtain (\ref{fhk}) provided that $t_{1n_{j}}$
vanishes as $n_{j}\rightarrow \infty $.

Next, write the first term in the r.h.s. of (\ref{hkn}) for $z=-\xi \in
I_{-} $ as 
\begin{equation*}
\int_{0}^{\infty }\frac{\lambda \nu _{R_{n_{j}}}(d\lambda )}{\lambda k(-\xi
)+\xi }+(\overline{k}_{n_{j}}(-\xi )-k(-\xi ))\int_{0}^{\infty }\frac{ 
\lambda ^{2}\nu _{R_{n_{j}}}(d\lambda )}{(\lambda k(-\xi )+\xi )(\lambda
\overline{k}_{n_{j}}(-\xi )+\xi )}.
\end{equation*} 
It follows then from (\ref{r2}), (\ref{nur}) and (\ref{pos}) that the first
term tends to the r.h.s. of (\ref{hk}) as $n_{j}\rightarrow \infty $. The
integral in the second term is bounded by $r_{2}/\xi ^{2}$ in view of (\ref 
{r2}) and (\ref{pos}), hence, the second term vanishes as $n_{j}\rightarrow
\infty $. Thus, we obtain (\ref{hk}) provided that $t_{2n_{j}}$ vanishes as $ 
n_{j}\rightarrow \infty $.

An analogous argument applies to (\ref{khn}). However, to obtain (\ref{kh})
and (\ref{nuka}), we have to find the limiting probability law of the random variable
$\eta _{jn}$ of (\ref{nukn0}). It follows from the standard facts on the
Central Limit Theorem (see, e.g. \cite{Sh:96}, Section III.4), (\ref{m4})
and (\ref{qqn}) that the law is Gaussian of zero mean and variance $q-\sigma
_{b}^{2}$, see Lemma \ref{l:clt} for details. This proves (\ref{kh}).

Thus, we have proved the validity of (\ref{fhk}) -- (\ref{nuka}) for $z\in
I_{-}$ of (\ref{imi}) provided that $t_{1n}$ and $t_{2n}$ of (\ref{t10}) and
(\ref{t20}) vanish uniformly in $z\in I_{-}$. It is shown in Lemma \ref 
{l:uniq} that the system (\ref{hk}) -- (\ref{kh}) is well defined and
uniquely solvable everywhere in $\mathbb{C}\setminus \mathbb{R}_{+}$. This
implies that the whole sequences $\{f_{\mathcal{M}_{n}}\},\{\overline{h} 
_{n}\}$ and $\{\overline{k}_{n}\}$ converge uniformly on any compact set of $ 
\mathbb{C}\setminus \mathbb{R}_{+}$, that their limits $f_{\mathcal{M}},h$
and $k$ are not identically zero and can be found from relations (\ref{fhk})
-- (\ref{nuka}) which are valid everywhere in $\mathbb{C}\setminus \mathbb{R} 
_{+}$. Indeed, if $h$ is identically zero, then it follows from (\ref{kh})
with $z=-\xi <0$ that $k(-\xi )=k_{1}>0\,$, where $k_{1}$ is the first
moment of measure $\nu _{K}$ of (\ref{nuka}). Then (\ref{hk}) implies that $ 
\nu _{R}$ is concentrated at zero. This contradicts condition (a) of the
theorem. Analogously, assuming that $k$ is identically zero, we conclude
that $\nu _{K}$ of (\ref{nuka}) is concentrated at zero and this is
impossible if $\varphi $ is not identically constant.




Besides, it follows from  (\ref{pos})

that $k(-\xi )$ and $\xi h(-\xi )$ are nonnegative and bounded.  
Thus,
the limit $\xi \rightarrow \infty $ in (\ref{fhk}) yields (\ref{numr1}). Conditions (\ref{hcond}) follow from the $n \to \infty$ versions of
(\ref{hrep}) -- (\ref{pos}).

\smallskip
We pass now to the most technical part of the proof in which we establish
that the  error terms (\ref{t10}) and (\ref{t20}) vanish as $n \to \infty$ uniformly on $ 
z\in I_{- }$ of (\ref{imi}).

Note first that it suffices to assume that the sequence $\{R_{n}\}$ of (\ref 
{mncal}) -- (\ref{nur}) is uniformly bounded, i.e.,
\begin{equation}
\sup_{n}||R_{n}||\leq \rho <\infty ,  \label{rrho}
\end{equation} 
instead of (\ref{r2}). This is also a standard and technically convenient
trick of random matrix theory where it is shown that once the limiting
Normalized Counting Measure is found under condition (\ref{rrho}), it can be
also found under condition (\ref{r2}), see e.g. \cite{Pa-Sh:11}, Section 19,
in particular, Theorem 19.1.8 for the case where $K_{n}$ is independent of $ 
X_{n}$ of (\ref{Xn}). In our case of (\ref{Dn}) -- (\ref{Phi}) the proof of this fact is
given in \cite{Pa:20}.

By using (\ref{ct10}) and (\ref{t10}), we have from (\ref{tral}), (\ref{hns} 
) and (\ref{kns}) 
\begin{align}
t_{1n}(-\xi )& =\frac{1}{zn}\sum_{j=1}^{n}\mathbf{E} 
\{a_{j}K_{j}(1+K_{j}a_{j})^{-1}-\overline{h}_{n}K_{j}(1+K_{j}\overline{h} 
_{n})^{-1}\}|_{z=-\xi }  \notag \\
& =-\frac{1}{zn}\sum_{j=1}^{n}\mathbf{E}\{(a_{j}-\overline{h} 
_{n})K_{j}((1+K_{j}a_{j})(1+K_{j}\overline{h}_{n}))^{-1}\}|_{z=-\xi }.
\label{t11}
\end{align} 
It follows then from (\ref{aj}) -- (\ref{pos}) that
\begin{equation}
(1+K_{j}a_{j}(-\xi ))\geq 1,\;(1+K_{j}\overline{h}_{n}(-\xi ))\geq 1.
\label{den}
\end{equation} 
These bounds, (\ref{pos}) and (\ref{t11}) imply 
\begin{equation}
|t_{1n}(-\xi )|\leq \Phi
_{1}^{2}d_{1}\xi^{-1},\;d_{1}=n^{-1}\sum_{j=1}^{n}d_{1j},\;d_{1j}=\mathbf{E}\{|a_{j}- 
\overline{h}_{n}|\}.  \label{t12}
\end{equation} 
According to Lemma \ref{l:dif}, $d_{1j}\leq C^{\prime }/n^{1/2}$ if $n$ is
large enough and we obtain  
\begin{equation}
|t_{1n}(-\xi )|\leq C_{1}/n^{1/2},\;C_{1}=\Phi _{1}^{4}C^{\prime } \xi^{-1}.
\label{toc1}
\end{equation} 
This and (\ref{fhkn}) justify (\ref{fhk}).

Consider now $t_{2n}$ of (\ref{t20}). Using an argument similar to that
leading to (\ref{t11}), we obtain
\begin{align}
